<script setup>import {ref,onMounted} from 'vue';import {api} from '../core';import ProductCard from '../components/ProductCard.vue';import State from '../components/State.vue';import Icon from '../components/Icon.vue';const keyword=ref(''),category=ref(''),page=ref(1),result=ref({items:[],total:0,categories:[]}),loading=ref(false),error=ref('');async function load(reset=false){if(reset)page.value=1;loading.value=true;error.value='';try{result.value=await api('/products?'+new URLSearchParams({keyword:keyword.value,category:category.value,page:page.value}))}catch(e){error.value=e.message}finally{loading.value=false}}onMounted(()=>load());</script><template><div class="shop-intro shell"><div><p class="eyebrow">GOOD THINGS FOR GOOD COMPANIONS</p><h1>小小日常，满满的爱。</h1><p>为它挑选合适的好物，让陪伴更舒服一点。</p><span class="offer-label">模拟优惠 · 满减后再享八折</span></div><img src="/assets/shop-hero.webp" alt="宠物食品和日常用品"></div><section class="shell section"><form class="filter-bar" @submit.prevent="load(true)"><label class="search-field"><Icon name="search"/><input v-model="keyword" aria-label="搜索商品" placeholder="为它找点什么？"></label><button class="btn">搜索好物</button></form><div class="category-tabs"><button :class="{active:category===''}" @click="category='';load(true)">全部好物</button><button v-for="c in result.categories" :key="c" :class="{active:category===c}" @click="category=c;load(true)">{{c}}</button></div><div class="section-heading compact"><p>共 {{result.total}} 件好物</p><RouterLink to="/cart" class="quiet-link">查看购物车 <Icon name="bag" :size="18"/></RouterLink></div><State :loading="loading" :error="error" :empty="!result.items.length" text="没有找到商品，换个关键词试试" @retry="load()"/><div class="product-grid" v-if="!loading&&!error"><ProductCard v-for="p in result.items" :key="p.id" :product="p"/></div><div class="pagination"><button class="btn secondary small" :disabled="page===1||loading" @click="page--;load()">上一页</button><span>{{page}} / {{Math.max(1,Math.ceil(result.total/12))}}</span><button class="btn secondary small" :disabled="page*12>=result.total||loading" @click="page++;load()">下一页</button></div></section></template>
